-- Fuller step-by-step instructions for 30 of the best-known seed recipes (5 to 7 steps each).
-- Replaces the short three-step versions from world_recipes.sql; amounts follow recipe_quantities.sql.
-- Run after world_recipes.sql. Safe to run more than once.
insert into public.recipe_steps (recipe_id, step_number, instruction)
select r.id, v.step_number, v.instruction
from (values
  ('world-001', 1, 'Rinse 1 cup of red lentils in several changes of water until it runs almost clear.'),
  ('world-001', 2, 'Put the lentils in a pot with 3 cups of water, the turmeric and a teaspoon of salt. Bring to a boil and skim off the foam.'),
  ('world-001', 3, 'Lower the heat, partly cover and simmer for 15 to 20 minutes, stirring now and then, until the lentils have broken down. Add hot water if it gets too thick.'),
  ('world-001', 4, 'Whisk the dal for a few seconds so it turns smooth and soupy.'),
  ('world-001', 5, 'In a small pan, heat the oil and fry the sliced onion until golden, then add the sliced garlic and the chilies and fry for another minute.'),
  ('world-001', 6, 'Pour the hot onion mixture into the dal, stir, simmer for 2 minutes and taste for salt. Serve with rice.'),
  ('world-004', 1, 'Hard-boil the eggs for 9 minutes, cool them in cold water and peel.'),
  ('world-004', 2, 'Prick each egg a few times with a fork, rub with a pinch of turmeric and salt, and fry in the oil over medium heat until lightly blistered. Lift them out.'),
  ('world-004', 3, 'In the same oil, cook the finely sliced onions for 8 to 10 minutes until deep golden.'),
  ('world-004', 4, 'Add the crushed garlic and ginger and fry for a minute, then add the chopped tomatoes, turmeric, chili powder and salt.'),
  ('world-004', 5, 'Cook, adding a splash of water whenever the pan dries, until the tomatoes have melted and oil shows at the edges, about 8 minutes.'),
  ('world-004', 6, 'Return the eggs with a quarter cup of water, cover and simmer for 5 minutes so the masala clings to them.'),
  ('world-005', 1, 'Dry-roast the moong lentils in a heavy pot over medium heat for 3 to 4 minutes, stirring, until they smell nutty. Wash them together with the rice and drain.'),
  ('world-005', 2, 'Heat the ghee in the same pot and add the bay leaves and cumin. When they sizzle, add the sliced onion and fry until golden.'),
  ('world-005', 3, 'Stir in the grated ginger and garlic and cook for a minute.'),
  ('world-005', 4, 'Add the rice and lentils with the turmeric and salt and fry for 3 to 4 minutes, stirring so nothing sticks.'),
  ('world-005', 5, 'Pour in 3 cups of hot water, bring to a boil, then cover tightly and cook on the lowest heat for 18 to 20 minutes.'),
  ('world-005', 6, 'Rest off the heat, still covered, for 5 minutes, then fluff gently with a fork.'),
  ('world-008', 1, 'Cut the beef into bite-size pieces and pat dry.'),
  ('world-008', 2, 'Heat the oil in a heavy pot and fry the sliced onions over medium heat for 12 to 15 minutes until well browned.'),
  ('world-008', 3, 'Add the crushed garlic and ginger and fry for 2 minutes.'),
  ('world-008', 4, 'Add the beef with the turmeric, chili powder, cumin and salt. Fry on high heat for 8 to 10 minutes, stirring, until the meat is sealed and the spices smell cooked.'),
  ('world-008', 5, 'Add half a cup of hot water, cover and cook on low heat for about an hour, stirring every 15 minutes and adding a splash of water if it starts to stick.'),
  ('world-008', 6, 'When the beef is tender, uncover and cook down until the gravy is thick and coats the meat.'),
  ('world-008', 7, 'Sprinkle with the garam masala, rest for 5 minutes and serve.'),
  ('world-009', 1, 'Cut the chicken into pieces and halve the potatoes. Rub the potatoes with a pinch of turmeric and salt.'),
  ('world-009', 2, 'Heat the oil and fry the potatoes until golden on the outside, then lift them out.'),
  ('world-009', 3, 'In the same oil, fry the sliced onions until light brown, then add the garlic and ginger and cook for a minute.'),
  ('world-009', 4, 'Add the chicken, turmeric, chili powder, cumin and salt. Fry over medium-high heat for 10 minutes, stirring, until the chicken is sealed and the oil separates.'),
  ('world-009', 5, 'Pour in 2 cups of hot water, add the potatoes and bring to a boil.'),
  ('world-009', 6, 'Cover and simmer for 20 to 25 minutes until the chicken is cooked through and the potatoes are soft. The gravy should stay thin.'),
  ('world-014', 1, 'Rub the fish pieces with half the turmeric and a little salt and leave for 10 minutes.'),
  ('world-014', 2, 'Heat the oil until hot and fry the fish for a minute or two on each side until lightly golden. Lift out carefully.'),
  ('world-014', 3, 'Fry the potato wedges in the same oil until the edges colour, then set aside.'),
  ('world-014', 4, 'Add the cumin and sliced onion to the pan and cook until soft, then add the chopped tomato, the remaining turmeric, the chilies and salt. Cook until the tomato breaks down.'),
  ('world-014', 5, 'Add 2 cups of hot water and the potatoes and simmer for 10 minutes until nearly tender.'),
  ('world-014', 6, 'Slide in the fish and simmer gently for 8 minutes without stirring hard. Finish with the cilantro.'),
  ('world-018', 1, 'Marinate the chicken in the yogurt, ginger, garlic and salt for at least 30 minutes. Wash the rice and soak it for 20 minutes.'),
  ('world-018', 2, 'Fry the sliced onions in half the ghee until golden brown and set half of them aside for the top.'),
  ('world-018', 3, 'Add the cardamom, cinnamon and bay leaves to the pot, then the chicken with its marinade. Cook, covered, over medium-low heat for 25 to 30 minutes until tender.'),
  ('world-018', 4, 'In another pot, fry the drained rice in the remaining ghee for 2 minutes. Add 3 cups of hot water, the milk and salt, and cook until the rice is half done and most of the liquid is absorbed.'),
  ('world-018', 5, 'Layer the chicken and its gravy into the rice and scatter over the reserved onions.'),
  ('world-018', 6, 'Cover tightly and steam on the lowest heat for 20 minutes. Rest for 5 minutes before lifting gently from the bottom.'),
  ('world-021', 1, 'Blanch the spinach in boiling water for 2 minutes, drain, and cool it in cold water to keep the colour. Blend to a smooth puree.'),
  ('world-021', 2, 'Cut the paneer into cubes. If you like, fry them lightly in a little of the oil until golden and set aside.'),
  ('world-021', 3, 'Heat the oil and add the cumin. When it sizzles, add the chopped onion and cook until soft and lightly golden.'),
  ('world-021', 4, 'Add the garlic and ginger, cook for a minute, then add the chopped tomato and cook until soft.'),
  ('world-021', 5, 'Stir in the garam masala and salt, then the spinach puree and a splash of water. Simmer for 5 minutes.'),
  ('world-021', 6, 'Add the paneer and simmer for 3 minutes more, then stir in the cream off the heat.'),
  ('world-022', 1, 'Heat the oil and add the cumin. When it sizzles, add the finely chopped onions and cook for 10 minutes until well browned.'),
  ('world-022', 2, 'Add the garlic and ginger and fry for a minute.'),
  ('world-022', 3, 'Add the chopped tomatoes with the ground coriander, turmeric, chili powder and salt. Cook for 8 to 10 minutes, mashing the tomatoes, until the oil separates.'),
  ('world-022', 4, 'Add the cooked chickpeas and one and a half cups of water or chickpea cooking liquid.'),
  ('world-022', 5, 'Simmer for 15 minutes, lightly crushing a few chickpeas against the side of the pot to thicken the gravy.'),
  ('world-022', 6, 'Stir in the garam masala, taste for salt and rest for 5 minutes before serving.'),
  ('world-023', 1, 'Cut the potatoes into small cubes and the cauliflower into florets of a similar size.'),
  ('world-023', 2, 'Heat the oil and add the cumin. When it sizzles, add the sliced onion and cook until soft.'),
  ('world-023', 3, 'Add the grated ginger and the chopped tomatoes and cook for 3 minutes.'),
  ('world-023', 4, 'Add the potatoes with the turmeric, ground coriander, chili and salt. Stir, cover and cook on low heat for 8 minutes.'),
  ('world-023', 5, 'Add the cauliflower, stir gently to coat, cover again and cook for 12 to 15 minutes, stirring once or twice. Add a spoonful of water only if it sticks.'),
  ('world-023', 6, 'Uncover for the last 2 minutes so the vegetables dry out and catch a little colour.'),
  ('world-024', 1, 'Rinse the lentils and put them in a pot with 3 cups of water, the turmeric, the chopped tomato and salt.'),
  ('world-024', 2, 'Bring to a boil, then simmer partly covered for 25 to 30 minutes until completely soft. Whisk until creamy, adding hot water to loosen.'),
  ('world-024', 3, 'For the tadka, heat the ghee in a small pan and add the mustard seeds. When they pop, add the cumin.'),
  ('world-024', 4, 'Add the sliced onion and fry until golden, then the sliced garlic and the dried chilies for 30 seconds.'),
  ('world-024', 5, 'Pour the sizzling tadka over the dal, cover for a minute to trap the aroma, then stir it through.'),
  ('world-026', 1, 'Cut the chicken into chunks and marinate in the yogurt, half the garlic and ginger, the chili powder and salt for at least 30 minutes.'),
  ('world-026', 2, 'Sear the chicken in a hot pan or under a grill until charred at the edges and almost cooked. Set aside.'),
  ('world-026', 3, 'Melt half the butter in a pot and cook the remaining garlic and ginger for a minute. Add the chopped tomatoes and cook for 15 minutes until completely broken down.'),
  ('world-026', 4, 'Blend the sauce until smooth and return it to the pot.'),
  ('world-026', 5, 'Add the chicken, the garam masala and the remaining butter and simmer for 10 minutes.'),
  ('world-026', 6, 'Stir in the cream, warm through without boiling and taste for salt.'),
  ('world-033', 1, 'Cut the chicken into large chunks.'),
  ('world-033', 2, 'Mix the yogurt, garlic, ginger, garam masala, paprika, lemon juice, oil and salt into a thick marinade.'),
  ('world-033', 3, 'Coat the chicken well and marinate for at least 20 minutes, or up to a day in the fridge.'),
  ('world-033', 4, 'Thread the pieces onto skewers, leaving small gaps between them.'),
  ('world-033', 5, 'Cook under a very hot grill or in a 230°C oven for 12 to 15 minutes, turning once, until charred in spots and cooked through.'),
  ('world-033', 6, 'Rest for 3 minutes and serve with lemon wedges.'),
  ('world-036', 1, 'Mix the flour with a pinch of salt and enough water, about three quarters of a cup, to make a soft dough. Knead for 5 minutes, cover and rest for 15 minutes.'),
  ('world-036', 2, 'Boil the potatoes until tender, peel and mash until there are no lumps. Mix in the chopped chili, cilantro, cumin and salt, and let the filling cool.'),
  ('world-036', 3, 'Divide the dough and the filling into 6 portions each.'),
  ('world-036', 4, 'Flatten a ball of dough, place a portion of filling in the middle, gather the edges over it and pinch to seal.'),
  ('world-036', 5, 'Dust with flour and roll out gently, seam side down, into a round about 18 cm across.'),
  ('world-036', 6, 'Cook on a hot dry pan for a minute on each side, then brush both sides with ghee and cook until golden brown spots appear.'),
  ('world-041', 1, 'Use rice cooked the day before, or cook it early and spread it out to cool and dry. Break up any clumps with your fingers.'),
  ('world-041', 2, 'Beat the eggs with a pinch of salt. Slice the spring onions, keeping the white and green parts separate.'),
  ('world-041', 3, 'Heat half the oil in a wok or wide pan over high heat. Pour in the eggs, scramble until just set and tip them out.'),
  ('world-041', 4, 'Add the remaining oil and the white parts of the spring onion, then the rice. Stir-fry for 3 to 4 minutes, pressing out lumps, until every grain is hot.'),
  ('world-041', 5, 'Add the soy sauce around the edge of the pan, return the egg and toss for another minute.'),
  ('world-041', 6, 'Stir in the green spring onion, taste for salt and serve at once.'),
  ('world-043', 1, 'Cut the tofu into 2 cm cubes and soak them in hot salted water for 5 minutes, then drain. This firms them up.'),
  ('world-043', 2, 'Finely chop the mushrooms, garlic and ginger. Slice the spring onions.'),
  ('world-043', 3, 'Heat the oil and fry the mushrooms over high heat until they have released their water and browned.'),
  ('world-043', 4, 'Add the garlic, ginger and chili and fry for 30 seconds until fragrant.'),
  ('world-043', 5, 'Add the soy sauce and a cup of water, bring to a simmer and slide in the tofu. Simmer for 5 minutes, pushing the tofu gently rather than stirring.'),
  ('world-043', 6, 'Mix the cornstarch with 2 tablespoons of water, pour it in and simmer until the sauce turns glossy. Top with the spring onion.'),
  ('world-044', 1, 'Dice the chicken and toss with 1 tablespoon of the soy sauce and half the cornstarch. Leave for 10 minutes.'),
  ('world-044', 2, 'Mix the remaining soy sauce and cornstarch with the vinegar, sugar and 2 tablespoons of water to make the sauce.'),
  ('world-044', 3, 'Heat the oil in a wok and fry the dried chilies until they darken, about 20 seconds.'),
  ('world-044', 4, 'Add the chicken and stir-fry over high heat for 3 to 4 minutes until just cooked.'),
  ('world-044', 5, 'Add the garlic, ginger and the white parts of the spring onion and fry for 30 seconds.'),
  ('world-044', 6, 'Pour in the sauce and toss until it thickens and coats the chicken, then stir in the peanuts and the green spring onion.'),
  ('world-048', 1, 'Slice the beef thinly across the grain. Toss with 1 tablespoon of the soy sauce and the cornstarch and leave for 15 minutes.'),
  ('world-048', 2, 'Cut the broccoli into small florets and blanch in boiling water for 1 minute. Drain well.'),
  ('world-048', 3, 'Mix the oyster sauce, the remaining soy sauce and 3 tablespoons of water.'),
  ('world-048', 4, 'Heat the oil in a wok until very hot and sear the beef in a single layer for a minute on each side. Lift it out.'),
  ('world-048', 5, 'Fry the garlic and ginger for 20 seconds, add the broccoli and toss for a minute.'),
  ('world-048', 6, 'Return the beef, pour in the sauce and toss for a minute until everything is glossy.'),
  ('world-049', 1, 'Boil the noodles until just tender, rinse under cold water, drain well and toss with a teaspoon of oil.'),
  ('world-049', 2, 'Shred the cabbage, cut the carrot into thin matchsticks and slice the spring onions.'),
  ('world-049', 3, 'Heat the oil in a wok over high heat and stir-fry the carrot and cabbage for 2 minutes so they stay crisp.'),
  ('world-049', 4, 'Add the noodles and the soy sauce and toss for 2 to 3 minutes, letting the noodles catch a little on the pan.'),
  ('world-049', 5, 'Add the bean sprouts and spring onion and toss for 30 seconds.'),
  ('world-049', 6, 'Finish with the sesame oil and serve straight away.'),
  ('world-050', 1, 'Cut the chicken into bite-size pieces and coat them in 3 tablespoons of the cornstarch.'),
  ('world-050', 2, 'Mix the vinegar, sugar, soy sauce, the remaining cornstarch and 4 tablespoons of water to make the sauce.'),
  ('world-050', 3, 'Heat about 2 cm of oil in a pan and fry the chicken in batches for 4 to 5 minutes until crisp and cooked through. Drain on paper.'),
  ('world-050', 4, 'Pour off all but a tablespoon of oil. Stir-fry the onion and bell pepper chunks for 2 minutes, then add the pineapple.'),
  ('world-050', 5, 'Pour in the sauce and boil for a minute until thick and glossy.'),
  ('world-050', 6, 'Toss the chicken through the sauce and serve immediately so it stays crisp.'),
  ('world-061', 1, 'Finely chop the onion, chili, tomato and cilantro. Rinse the chopped onion under cold water for a milder taste.'),
  ('world-061', 2, 'Halve the avocados, remove the stones and scoop the flesh into a bowl.'),
  ('world-061', 3, 'Add the lime juice and salt and mash with a fork, leaving it a little chunky.'),
  ('world-061', 4, 'Fold in the onion, chili, tomato and cilantro.'),
  ('world-061', 5, 'Taste and adjust the salt and lime. Serve straight away, or press cling film onto the surface to stop it browning.'),
  ('world-064', 1, 'Slice the onion and bell pepper and shred the cooked chicken.'),
  ('world-064', 2, 'Heat half the oil and fry the onion and pepper with the cumin for 5 minutes until soft. Stir in the chicken and salt and warm through.'),
  ('world-064', 3, 'Lay out the tortillas. Sprinkle cheese over half of each, add the filling, then a little more cheese, and fold over.'),
