  ('world-066', 1, 'Rinse the rice and drain it well.'),
  ('world-066', 2, 'Blend the tomatoes, onion and garlic to a smooth puree.'),
  ('world-066', 3, 'Heat the oil in a pot and fry the rice over medium heat for 4 to 5 minutes, stirring, until it turns golden.'),
  ('world-066', 4, 'Add the tomato puree and cook for 3 minutes until it darkens and most of the liquid has gone.'),
  ('world-066', 5, 'Add the stock, cumin and salt and bring to a boil.'),
  ('world-066', 6, 'Cover and cook on the lowest heat for 18 minutes, then rest covered for 5 minutes and fluff with a fork.'),
  ('world-068', 1, 'Poach the chicken in simmering salted water for 20 minutes until cooked through. Cool slightly and shred with two forks.'),
  ('world-068', 2, 'Blend the tomatoes, garlic and chipotle chilies until smooth.'),
  ('world-068', 3, 'Heat the oil and cook the sliced onion over medium heat for 8 minutes until soft and lightly golden.'),
  ('world-068', 4, 'Add the sauce, oregano and salt and simmer for 5 minutes.'),
  ('world-068', 5, 'Stir in the chicken and simmer for 10 minutes until the sauce has thickened and coats the meat.'),
  ('world-068', 6, 'Serve on crisp or warm tortillas.'),
  ('world-071', 1, 'Mix the lime juice, crushed garlic, cumin, oil and salt. Coat the beef and marinate for 15 to 30 minutes.'),
  ('world-071', 2, 'Finely chop the onion and cilantro for the topping.'),
  ('world-071', 3, 'Heat a heavy pan or grill until smoking hot. Cook the beef for 2 to 3 minutes on each side for medium.'),
  ('world-071', 4, 'Rest the meat for 5 minutes, then chop into small pieces across the grain.'),
  ('world-071', 5, 'Warm the tortillas in a dry pan for 20 seconds on each side.'),
  ('world-071', 6, 'Fill with the beef, onion and cilantro and serve with lime wedges.'),
  ('world-081', 1, 'Soak the rice noodles in warm water for 20 to 30 minutes until pliable but still firm, then drain.'),
  ('world-081', 2, 'Mix the tamarind paste, fish sauce and sugar with 2 tablespoons of water to make the sauce.'),
  ('world-081', 3, 'Heat half the oil in a wok over high heat. Fry the cubed tofu until golden, then add the shrimp and cook until just pink. Push everything to one side.'),
  ('world-081', 4, 'Add the remaining oil, crack in the eggs, scramble until just set and mix with the tofu and shrimp.'),
  ('world-081', 5, 'Add the noodles and the sauce and toss for 2 to 3 minutes until the noodles are tender. Add a splash of water if they stick.'),
  ('world-081', 6, 'Toss in the bean sprouts and spring onion for 30 seconds.'),
  ('world-081', 7, 'Serve with the crushed peanuts and lime wedges.'),
  ('world-082', 1, 'Cut the chicken into thin slices and the eggplant into bite-size cubes.'),
  ('world-082', 2, 'Spoon the thick cream from the top of the coconut milk, about 4 tablespoons, into a pot with the oil and heat until it bubbles.'),
  ('world-082', 3, 'Add the curry paste and fry for 2 minutes until fragrant.'),
  ('world-082', 4, 'Add the chicken and stir to coat, then pour in the rest of the coconut milk and bring to a gentle simmer.'),
  ('world-082', 5, 'Add the eggplant, fish sauce and sugar and simmer for 8 to 10 minutes until the chicken is cooked and the eggplant is tender.'),
  ('world-082', 6, 'Stir in the basil leaves, take off the heat and serve with rice.'),
